// Local document library. Blobs stay in IndexedDB on this browser / origin.
let documentItems=[],documentLibraryStatus='idle',documentLibraryError='',documentUploadBusy=false;
const documentUrls=new Map();let documentDbPromise;
function documentDb(){if(!documentDbPromise)documentDbPromise=new Promise((resolve,reject)=>{if(typeof indexedDB==='undefined'){reject(Error('Dieser Browser stellt keinen lokalen Dokumentenspeicher bereit.'));return}const req=indexedDB.open('gut-begleitet-documents',1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'id'});req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result)};req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('Bitte andere geöffnete App-Tabs schließen und neu laden.'))}).catch(error=>{documentDbPromise=undefined;throw error});return documentDbPromise}
async function documentStore(mode,action){const db=await documentDb();return new Promise((resolve,reject)=>{const tx=db.transaction('files',mode),req=action(tx.objectStore('files'));let result;req.onsuccess=()=>{result=req.result};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error||req.error);tx.onabort=()=>reject(tx.error||Error('Speichern abgebrochen.'))})}
function refreshDocumentsView(){if(location.hash==='#dokumente')render()}
async function loadDocuments(){if(documentLibraryStatus==='loading')return;documentLibraryStatus='loading';try{documentItems=(await documentStore('readonly',store=>store.getAll())).sort((a,b)=>b.created-a.created);documentLibraryStatus='ready';documentLibraryError=''}catch(e){documentLibraryStatus='error';documentLibraryError=e.message||'Dokumente konnten nicht geladen werden.'}refreshDocumentsView()}
function localDocumentUrl(item){if(!documentUrls.has(item.id))documentUrls.set(item.id,URL.createObjectURL(item.blob));return documentUrls.get(item.id)}
function documentSize(bytes){return bytes<1048576?Math.max(1,Math.round(bytes/1024))+' KB':(bytes/1048576).toFixed(1)+' MB'}
function documentLibrary(){if(documentLibraryStatus==='idle')void loadDocuments();return `${intro('Dokumente','Wichtige Unterlagen an einem Ort.','Arztbriefe, Befunde und eigene Vorsorgedokumente griffbereit halten.')}<section class="panel"><h2>Eigene Dokumente ablegen</h2><p>PDFs oder Fotos auswählen. Am Smartphone kannst du Unterlagen auch mit der Kamera fotografieren.</p><div class="document-upload-actions"><label class="primary file-label">Dateien hochladen<input type="file" accept="application/pdf,image/*,.pdf,.heic,.heif" multiple onchange="uploadDocuments(this)"></label><label class="secondary file-label">Kamera verwenden<input type="file" accept="image/*" capture="environment" onchange="uploadDocuments(this)"></label></div><p class="source">Bis 20 MB je Datei. Ein Kamerafoto ist noch kein PDF-Scan; es wird als Bild gespeichert. Die Kameraauswahl hängt vom Smartphone und Browser ab.</p><p class="note">Die Ablage bleibt ausschließlich in diesem Browser auf diesem Gerät, ohne zusätzliche Verschlüsselung durch die App. Kein Upload auf die Synology und keine Synchronisierung. Beim Löschen der Browserdaten können Dokumente verloren gehen – Originale und Sicherungskopien separat aufbewahren.</p><p role="status" id="document-status">${documentUploadBusy?'Dateien werden gespeichert …':escapeQuestion(documentLibraryError)}</p></section><section class="document-library" aria-labelledby="document-library-title"><div class="section-head"><h2 id="document-library-title">Meine Dokumente</h2><span class="source">${documentItems.length} gespeichert</span></div>${documentLibraryStatus==='loading'?'<p role="status">Dokumente werden geladen …</p>':documentLibraryStatus==='error'?'<button class="secondary" onclick="loadDocuments()">Erneut laden</button>':''}<div class="benefit-grid">${documentItems.map(item=>`<article class="panel document-card"><span class="tag">${escapeQuestion(item.diseaseName||'Allgemein')}</span><h3>${escapeQuestion(item.name)}</h3><p class="source">${item.type==='application/pdf'?'PDF':'Bild'} · ${documentSize(item.size)} · ${new Date(item.created).toLocaleDateString('de-DE')}</p><div class="document-card-actions"><button class="secondary" onclick="previewDocument('${item.id}')">Ansehen</button><a class="plain" href="${localDocumentUrl(item)}" download="${escapeQuestion(item.name)}">Herunterladen</a><button class="plain question-delete" onclick="askDeleteDocument('${item.id}')">Löschen</button></div></article>`).join('')|| (documentLibraryStatus==='ready'?'<p class="muted">Noch keine eigenen Dokumente abgelegt.</p>':'')}</div></section><section class="document-templates"><div class="section-head"><h2>Offizielle Vorsorge-Vorlagen</h2><span class="tag">Deutschland</span></div><p>${state.country==='DE'?'Die beiden Original-PDFs sind direkt in der App enthalten.':'Du hast '+escapeQuestion(countries[state.country])+' gewählt. Diese zwei Vorlagen beziehen sich auf Deutschland. Für deine Vorsorge bitte landesspezifische Unterlagen und Beratung verwenden.'}</p><div class="benefit-grid">${officialDocumentTemplates.map((t,i)=>`<article class="panel"><h3>${t.title}</h3><p>${t.description}</p><p class="source">Bundesministerium der Justiz · ${t.pages} Seiten · unveränderte Originaldatei, abgerufen am 25.10.2026</p><a class="primary benefit-link" href="${officialTemplateUrl(i)}" download="${t.filename}">PDF herunterladen</a><p><a href="${officialTemplateUrl(i)}" target="_blank" rel="noopener">PDF öffnen ↗</a></p><p class="source">Falls kein Download startet: PDF öffnen und dort die Speicher- oder Teilen-Funktion nutzen.</p><p><a href="${t.source}" target="_blank" rel="noopener">Offizielle Quelle ↗</a></p></article>`).join('')}</div><p class="note">Vorlagen persönlich ausfüllen und die jeweiligen Form- und Unterschriftserfordernisse beachten. Die Patientenverfügung enthält alternative Textbausteine, keine fertige persönliche Erklärung. Eine Vorsorgevollmacht ersetzt je nach Geschäft keine gesonderte Bankvollmacht, Beglaubigung oder notarielle Beurkundung. Eine gespeicherte Kopie ersetzt kein erforderliches Original.</p></section>`}
async function uploadDocuments(input){if(documentUploadBusy)return;const files=Array.from(input.files||[]);if(!files.length)return;documentUploadBusy=true;documentLibraryError='';const disease=state.disease,diseaseName=currentCondition().name;refreshDocumentsView();const errors=[];for(const file of files){if(file.size===0){errors.push(file.name+': Datei ist leer.');continue}if(file.size>20*1024*1024){errors.push(file.name+': größer als 20 MB.');continue}let type=file.type;if(!type&&/\.pdf$/i.test(file.name))type='application/pdf';if(!type&&/\.(heic|heif)$/i.test(file.name))type='image/heic';if(type!=='application/pdf'&&!type.startsWith('image/')){errors.push(file.name+': Bitte PDF oder Bild auswählen.');continue}const record={id:'doc-'+(typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)),name:file.name||'Kamerafoto.jpg',type,size:file.size,blob:file,created:Date.now(),disease,diseaseName};try{await documentStore('readwrite',store=>store.put(record))}catch(e){errors.push(file.name+': Speichern fehlgeschlagen. Speicherplatz oder Browserberechtigung prüfen.')}}documentUploadBusy=false;input.value='';await loadDocuments();documentLibraryError=errors.join(' ');refreshDocumentsView()}
function previewDocument(id){const item=documentItems.find(x=>x.id===id);if(!item)return;const url=localDocumentUrl(item);modal('<div class="document-preview"><h2>'+escapeQuestion(item.name)+'</h2>'+(item.type==='application/pdf'?'<iframe title="PDF-Vorschau" src="'+url+'"></iframe>':/image\/(jpeg|png|gif|webp|avif|bmp)/.test(item.type)?'<img src="'+url+'" alt="Vorschau des gespeicherten Dokuments">':'<p>Für dieses Bildformat ist hier möglicherweise keine Vorschau verfügbar. Bitte herunterladen.</p>')+'<p><a class="primary benefit-link" href="'+url+'" download="'+escapeQuestion(item.name)+'">Datei herunterladen</a></p><p class="source">Falls dein Browser keine PDF-Vorschau unterstützt, lade die Datei herunter.</p></div>')}
function askDeleteDocument(id){const item=documentItems.find(x=>x.id===id);if(!item)return;modal('<h2>Dokument löschen?</h2><p>'+escapeQuestion(item.name)+' wird aus dieser lokalen Ablage entfernt.</p><div class="note-editor-actions"><button class="primary" onclick="deleteStoredDocument(\''+id+'\')">Dokument löschen</button><button class="secondary" onclick="document.getElementById(&quot;dialog&quot;).close()">Abbrechen</button></div><p id="document-delete-error" role="status"></p>')}
async function deleteStoredDocument(id){try{await documentStore('readwrite',store=>store.delete(id));if(documentUrls.has(id)){URL.revokeObjectURL(documentUrls.get(id));documentUrls.delete(id)}document.getElementById('dialog').close();await loadDocuments()}catch{document.getElementById('document-delete-error').textContent='Löschen fehlgeschlagen. Bitte erneut versuchen.'}}

const officialDocumentTemplates=[{"title":"Patientenverfügung – offizielle Textbausteine","description":"Formulierungshilfen zum persönlichen Zusammenstellen deiner Behandlungswünsche. Alternativen bewusst auswählen und die Erläuterungen beachten.","filename":"patientenverfuegung.pdf","pages":7,"source":"https://www.bmjv.de/SharedDocs/Downloads/DE/Formular/Patientenverfuegung_Textbausteine_pdf.pdf?__blob=publicationFile","data":"data:application/pdf;base64,"},{"title":"Vorsorgevollmacht – offizielles Formular","description":"Umfassendes Formular für ausgewählte Bereiche wie Gesundheit, Aufenthalt, Behörden und Vermögen. Den gewünschten Umfang persönlich festlegen; Sonderfälle können weitere Vollmachten oder notarielle Mitwirkung erfordern.","filename":"vorsorgevollmacht.pdf","pages":4,"source":"https://www.bmjv.de/SharedDocs/Downloads/DE/Formular/Vorsorgevollmacht.pdf?__blob=publicationFile","data":"data:application/pdf;base64,"}];

function officialTemplateUrl(index){const template=officialDocumentTemplates[index];if(!template)return "";const key="template-"+index;if(!documentUrls.has(key)){const binary=atob(template.data.split(",")[1]);const bytes=Uint8Array.from(binary,char=>char.charCodeAt(0));documentUrls.set(key,URL.createObjectURL(new Blob([bytes],{type:"application/pdf"})))}return documentUrls.get(key)}
